import{_ as n,o as a,c as p,ag as l}from"./chunks/framework.lghGfHnE.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"前端转AI Agent/26-ElasticSearch 全文检索：倒排索引表 + IK 分词器 + BM25 算法/index.md","filePath":"前端转AI Agent/26-ElasticSearch 全文检索：倒排索引表 + IK 分词器 + BM25 算法/index.md"}'),e={name:"前端转AI Agent/26-ElasticSearch 全文检索：倒排索引表 + IK 分词器 + BM25 算法/index.md"};function t(i,s,c,o,u,q){return a(),p("div",null,[...s[0]||(s[0]=[l(`<p>前面学了基于向量数据库 Milvus 实现 RAG 语义检索。</p><p>并且基于 LangGraph 实现了闭环的 Agentic RAG，也就是 Agent 自主决策要不要检索、用什么检索、信息够不够、效果怎么样、要不要重新搜。</p><p>具体的 Agentic RAG 要根据业务场景设计，理解这个闭环的思路就行。</p><p>但向量检索有个问题：</p><ul><li>专业术语、精确实体更适合关键词检索，纯语义检索容易匹配不准</li></ul><p>解决方案是：</p><ul><li>同时结合关键词检索与语义检索，由模型统一融合多路结果，提升专业场景准确率</li></ul><p>这里关键词检索用 ElasticSearch 中间件，它是专门用来实现全文检索的。</p><p>数据库是根，而中间件是特种兵。</p><p>我们会把原始数据存 MySQL，把需要检索的部分同步到 es 里。</p><p>这样关键词检索就可以走 es 了。</p><p>我们这节学一下 ElasticSearch 全文检索的中间件。</p><p>首先安装下 ES：</p><p>用上节学的 docker compose 的方式安装，之前我们安装 milvus 也是这样</p><p>创建一个目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir es-test</span></span>
<span class="line"><span>cd es-test</span></span>
<span class="line"><span>npm init -y</span></span></code></pre></div><p><img src="https://mmbiz.qpic.cn/sz_mmbiz_png/NMByQQfVwfcEUSdwGovRInYibzfCNvX8mQEJQu4ldUS45TGI6LslRcId4KLCPbBX7mHMAVy2tLy4MSIwxiaCLY89x2Isv5vpnXdXRp0Oe3OF0/640?wx_fmt=png&amp;from=appmsg&amp;tp=wxpic&amp;wxfrom=5&amp;wx_lazy=1#imgIndex=0" alt="图片" referrerpolicy="no-referrer"></p><p>添加这个 docker-compose.yml</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>version: &#39;3.8&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>services:</span></span>
<span class="line"><span># Elasticsearch 最新稳定版：8.17.0</span></span>
<span class="line"><span>  es:</span></span>
<span class="line"><span>    image: elasticsearch:8.17.0</span></span>
<span class="line"><span>    container_name: es-dev</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - &quot;9200:9200&quot;# ES 对外提供服务的端口</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      - discovery.type=single-node  # 单节点运行（开发环境）</span></span>
<span class="line"><span>      - xpack.security.enabled=false# 关闭安全认证，免密码访问</span></span>
<span class="line"><span>      - xpack.security.http.ssl.enabled=false# 关闭 HTTPS 加密</span></span>
<span class="line"><span>      - xpack.security.transport.ssl.enabled=false# 关闭节点传输加密</span></span>
<span class="line"><span>      - ES_JAVA_OPTS=-Xms512m -Xmx512m  # JVM 内存配置，避免占用过高</span></span>
<span class="line"><span>    volumes:</span></span>
<span class="line"><span>      - \${DOCKER_VOLUME_DIRECTORY:-.}/volumes/es:/usr/share/elasticsearch/data</span></span>
<span class="line"><span>    restart: always</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Kibana 最新稳定版：8.17.0（必须与 ES 版本完全一致）</span></span>
<span class="line"><span>  kibana:</span></span>
<span class="line"><span>    image: kibana:8.17.0</span></span>
<span class="line"><span>    container_name: kibana-dev</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - &quot;5601:5601&quot;# Kibana 网页控制台端口</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      - ELASTICSEARCH_HOSTS=http://es:9200  # 连接 ES 容器内部地址</span></span>
<span class="line"><span>    volumes:</span></span>
<span class="line"><span>      - \${DOCKER_VOLUME_DIRECTORY:-.}/volumes/kibana:/usr/share/kibana/data</span></span>
<span class="line"><span>    restart: always</span></span>
<span class="line"><span>    depends_on:</span></span>
<span class="line"><span>      - es  # 等待 ES 启动完成后再启动 Kibana</span></span>
<span class="line"><span></span></span>
<span class="line"><span>networks:</span></span>
<span class="line"><span>  default:</span></span>
<span class="line"><span>    name: common-network</span></span></code></pre></div><p>kibana 是 es 的一个可视化控制台</p><p>mysql 是表和行，在 es 里就是索引和文档</p><p><img src="https://mmbiz.qpic.cn/mmbiz_jpg/NMByQQfVwfc88mnQxAReDBmZQQkkUcibQjwD8Teia5XlrB0dYvDuVTibR6QwRFBCFMkPibUsB4R7TyWwFZRFsWSF9x6NoexxtgMR4qozn9icqw9g/640?wx_fmt=jpeg&amp;from=appmsg&amp;tp=wxpic&amp;wxfrom=5&amp;wx_lazy=1#imgIndex=1" alt="图片" referrerpolicy="no-referrer"></p><p>es 没有 sql，都是一些 http 的接口</p><p>我们试一下索引的创建和文档的增删改查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Elasticsearch 基础操作</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 1. 查看所有索引</span></span>
<span class="line"><span>GET /_cat/indices?v&amp;h=health,status,index,docs.count</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2. 创建索引</span></span>
<span class="line"><span>PUT /article</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;mappings&quot;: {</span></span>
<span class="line"><span>    &quot;properties&quot;: {</span></span>
<span class="line"><span>      &quot;title&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;text&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;content&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;text&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;author&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;keyword&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;createTime&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;date&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;viewCount&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;integer&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3. 查看索引结构</span></span>
<span class="line"><span>GET /article/_mapping</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 4. 查看索引配置</span></span>
<span class="line"><span>GET /article/_settings</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 5. 删除索引</span></span>
<span class="line"><span>DELETE /article</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ==========================</span></span>
<span class="line"><span># 文档 增删改查</span></span>
<span class="line"><span># ==========================</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 1. 新增文档（自动生成 ID）</span></span>
<span class="line"><span>POST /article/_doc</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;title&quot;: &quot;Elasticsearch 全文检索入门&quot;,</span></span>
<span class="line"><span>&quot;content&quot;: &quot;ES 基于倒排索引与 BM25 实现全文搜索，适用于文本检索场景&quot;,</span></span>
<span class="line"><span>&quot;author&quot;: &quot;后端开发&quot;,</span></span>
<span class="line"><span>&quot;createTime&quot;: &quot;2026-04-26&quot;,</span></span>
<span class="line"><span>&quot;viewCount&quot;: 128</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2. 新增文档（指定自定义 ID）</span></span>
<span class="line"><span>PUT /article/_doc/1001</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;title&quot;: &quot;RAG 混合检索实战&quot;,</span></span>
<span class="line"><span>&quot;content&quot;: &quot;ES 负责关键词检索，Milvus 负责向量语义检索，结合使用效果更佳&quot;,</span></span>
<span class="line"><span>&quot;author&quot;: &quot;AI开发&quot;,</span></span>
<span class="line"><span>&quot;createTime&quot;: &quot;2026-04-26&quot;,</span></span>
<span class="line"><span>&quot;viewCount&quot;: 256</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3. 根据 ID 查询单条</span></span>
<span class="line"><span>GET /article/_doc/1001</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 4. 查询全部文档</span></span>
<span class="line"><span>GET /article/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 5. 全文分词检索（text 字段）</span></span>
<span class="line"><span>GET /article/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match&quot;: {</span></span>
<span class="line"><span>      &quot;content&quot;: &quot;RAG 向量 检索&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 6. 精确匹配查询（keyword 字段）</span></span>
<span class="line"><span>GET /article/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;term&quot;: {</span></span>
<span class="line"><span>      &quot;author&quot;: &quot;AI开发&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 7. 只返回指定字段</span></span>
<span class="line"><span>GET /article/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;_source&quot;: [&quot;title&quot;, &quot;author&quot;],</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 8. 分页 + 排序</span></span>
<span class="line"><span>GET /article/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;from&quot;: 0,</span></span>
<span class="line"><span>&quot;size&quot;: 10,</span></span>
<span class="line"><span>&quot;sort&quot;: [</span></span>
<span class="line"><span>    {&quot;viewCount&quot;: &quot;desc&quot;}</span></span>
<span class="line"><span>  ],</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 9. 局部更新文档（推荐）</span></span>
<span class="line"><span>POST /article/_update/1001</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;doc&quot;: {</span></span>
<span class="line"><span>    &quot;viewCount&quot;: 999,</span></span>
<span class="line"><span>    &quot;title&quot;: &quot;RAG 混合检索高级实战&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 10. 全量覆盖更新</span></span>
<span class="line"><span>PUT /article/_doc/1001</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;title&quot;: &quot;全量覆盖测试&quot;,</span></span>
<span class="line"><span>&quot;content&quot;: &quot;原始内容被替换&quot;,</span></span>
<span class="line"><span>&quot;author&quot;: &quot;测试用户&quot;,</span></span>
<span class="line"><span>&quot;createTime&quot;: &quot;2026-04-26&quot;,</span></span>
<span class="line"><span>&quot;viewCount&quot;: 66</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 11. 根据 ID 删除文档</span></span>
<span class="line"><span>DELETE /article/_doc/1001</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 12. 条件批量删除</span></span>
<span class="line"><span>POST /article/_delete_by_query</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match&quot;: {</span></span>
<span class="line"><span>      &quot;author&quot;: &quot;后端开发&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 13. 统计文档总数</span></span>
<span class="line"><span>GET /article/_count</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 14. 清空索引数据（保留表结构）</span></span>
<span class="line"><span>POST /article/_delete_by_query</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我们测了一遍索引的创建、文档的增删改查，整体比较简单。</p><p>那用 es 和之前用 mysql 比有啥好处呢？</p><p>ES 相比 MySQL 最大的核心优势，本质来源于<strong>倒排索引</strong>的底层设计。</p><p><img src="https://mmbiz.qpic.cn/sz_mmbiz_jpg/NMByQQfVwfcSa0fdVQsoxD6pajpJdud9OZkr3LzV6icicVdAtsLwCNeicQyTvT69kdKib8OEF3w0c5OhDNiaiaD73Kkk5QmGWzvwZdU9vuH7iaQ1zM/640?wx_fmt=jpeg&amp;from=appmsg&amp;tp=wxpic&amp;wxfrom=5&amp;wx_lazy=1#imgIndex=2" alt="图片" referrerpolicy="no-referrer"></p><p>普通 MySQL 使用的是正向索引：</p><p>以一行为单位存储完整数据，检索文本内容时，需要逐行遍历、逐个字段匹配内容。数据量越大、文本越长，模糊 / 全文搜索就越慢，性能极差，并不适合大范围关键词检索。</p><p>而 Elasticsearch 采用<strong>倒排索引</strong>机制：</p><p>会自动对 text 类型字段进行分词处理，拆解为一个个独立词条，再以「词条」为核心，反向关联所有包含该词条的文档。</p><p>简单来说：</p><p>正向索引：文档 → 关键词</p><p>倒排索引：关键词 → 文档</p><p>基于这种结构，用户输入关键词检索时，ES 只需通过词条快速匹配对应的文档，无需全表遍历，就能实现海量文本下毫秒级的全文检索。</p><p>综上，ES 倒排索引的底层架构，就是专门为海量文本、关键词模糊检索、内容匹配场景量身设计的，这也是它吊打 MySQL 全文搜索的根本原因。</p><p>理解了倒排索引，就理解了 ES 了。</p><p>显然，在 ES 里分词是很重要的，不同的分词建的索引表都不同。</p><p>es 默认的 standard 分词器对中文支持不好：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /_analyze</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;analyzer&quot;: &quot;standard&quot;,</span></span>
<span class="line"><span>  &quot;text&quot;: &quot;Elasticsearch RAG 混合检索知识库&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><img src="https://mmbiz.qpic.cn/sz_mmbiz_png/NMByQQfVwfd14NlmtRXmmZbIXddxgNHecqXugDb3l9aOQpUEcFycLzCT1hwJtAhOu9znvODN1pvlp5luqngaHIcIjgG6HZssKA2PxDXSEVQ/640?wx_fmt=png&amp;from=appmsg&amp;tp=wxpic&amp;wxfrom=5&amp;wx_lazy=1#imgIndex=3" alt="图片" referrerpolicy="no-referrer"></p><p>它是每个字单独拆开的，而实际上应该 “混合”、“检索”分别是整体来建立索引</p><p>这就需要用 ik 分词器了</p><p>创建 elasticsarch/Dockerfile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 官方 ES 基础镜像</span></span>
<span class="line"><span>FROM elasticsearch:8.17.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 安装 IK 分词（版本严格和 ES 一致）</span></span>
<span class="line"><span>RUN elasticsearch-plugin install --batch \\</span></span>
<span class="line"><span>    https://release.infinilabs.com/analysis-ik/stable/elasticsearch-analysis-ik-8.17.0.zip</span></span></code></pre></div><p>就是 es 的容器里，执行命令安装 ik 分词器插件</p><p>我们用这个 Dockerfile 来构建 es 镜像</p><p>改一下 docker-compose.yml</p><p><img src="https://mmbiz.qpic.cn/sz_mmbiz_png/NMByQQfVwffMkn5AAlGsBJSFqiccX0mXx10iaLwic0VtDaAPbXkUa4LYU5Y2VfFXo0ETs4twMkic3AlKrpViaQ2lRTOka4pVibcKQyOabUSOUT8W8/640?wx_fmt=png&amp;from=appmsg&amp;tp=wxpic&amp;wxfrom=5&amp;wx_lazy=1#imgIndex=4" alt="图片" referrerpolicy="no-referrer"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Elasticsearch 8.17.0 + IK 中文分词（内置到镜像）</span></span>
<span class="line"><span>es:</span></span>
<span class="line"><span>  build: ./elasticsearch       # 从本地 Dockerfile 构建镜像（自带IK）</span></span>
<span class="line"><span>  container_name: es-dev</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>    - &quot;9200:9200&quot;               # ES 访问端口</span></span>
<span class="line"><span>  environment:</span></span>
<span class="line"><span>    - discovery.type=single-node  # 单节点运行（开发环境）</span></span>
<span class="line"><span>    - xpack.security.enabled=false# 关闭安全认证，免密码访问</span></span>
<span class="line"><span>    - xpack.security.http.ssl.enabled=false# 关闭 HTTPS 加密</span></span>
<span class="line"><span>    - xpack.security.transport.ssl.enabled=false# 关闭节点传输加密</span></span>
<span class="line"><span>    - ES_JAVA_OPTS=-Xms512m -Xmx512m  # JVM 内存配置，避免占用过高</span></span>
<span class="line"><span>  volumes:</span></span>
<span class="line"><span>    - \${DOCKER_VOLUME_DIRECTORY:-.}/volumes/es/data:/usr/share/elasticsearch/data</span></span>
<span class="line"><span>  restart: always</span></span></code></pre></div><p>试一下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker compose down</span></span>
<span class="line"><span>docker compose up -d --build</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 1. 检查 ES 状态</span></span>
<span class="line"><span>GET /</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2. 查看已安装插件</span></span>
<span class="line"><span>GET /_cat/plugins?v</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3. 原生 standard 分词</span></span>
<span class="line"><span>POST /_analyze</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;analyzer&quot;: &quot;standard&quot;,</span></span>
<span class="line"><span>&quot;text&quot;: &quot;Elasticsearch RAG 混合检索知识库&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 4. IK 细粒度分词（索引入库用）</span></span>
<span class="line"><span>POST /_analyze</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;analyzer&quot;: &quot;ik_max_word&quot;,</span></span>
<span class="line"><span>&quot;text&quot;: &quot;Elasticsearch RAG 混合检索知识库&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 5. IK 智能分词（搜索查询用）</span></span>
<span class="line"><span>POST /_analyze</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;analyzer&quot;: &quot;ik_smart&quot;,</span></span>
<span class="line"><span>&quot;text&quot;: &quot;Elasticsearch RAG 混合检索知识库&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>有了 ik 分词器之后，就可以快速的查询关键词对应的文档了。</p><p>之前是这样的：</p><p><img src="https://mmbiz.qpic.cn/mmbiz_jpg/NMByQQfVwfdBT8r3fx44PnDS0dxujJJLibiaah8FKiafTD4TVv7w1euGAs9bpQwZ6NWxLlhX9nmUicq3Evbic50ib3jdkLY2G3W7Zuuc2I7WFnu14/640?wx_fmt=jpeg&amp;from=appmsg&amp;tp=wxpic&amp;wxfrom=5&amp;wx_lazy=1#imgIndex=5" alt="图片" referrerpolicy="no-referrer"></p><p>把搜索词分词后，去索引表匹配，然后把结果合并返回。</p><p>默认 standard 分词器拆太细，索引的意义不大。</p><p>用了 ik 分词器是这样的：</p><p><img src="https://mmbiz.qpic.cn/sz_mmbiz_png/NMByQQfVwfdfPzgeYmj9wibuQFodwfJWygKkricOLIWybQfB3MxF9pRLl8dKW0voHicCGicO72vf8RqQf7Pt3O1BFObialAc0TX9GtS6Uy6hvgms/640?wx_fmt=png&amp;from=appmsg&amp;tp=wxpic&amp;wxfrom=5&amp;wx_lazy=1#imgIndex=6" alt="图片" referrerpolicy="no-referrer"></p><p>按照中文的词语来分词，建立倒排索引表。</p><p>查询的时候也用分词器分词，查询索引表，结果合并后返回。</p><p>这样的机制，自然可以毫秒级实现关键词检索。</p><p>之前创建 article 的索引用的是默认的分词器。</p><p>这次我们用 ik_max_word 来做索引生成，更细粒度（比如知识库会进一步细分为知识、库）</p><p>用 ik_smart 来做检索的分词</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Elasticsearch IK分词版操作手册</span></span>
<span class="line"><span># 索引：life_note</span></span>
<span class="line"><span># 字段全部配置 IK分词：入库 ik_max_word  /  查询 ik_smart</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 1. 查看所有索引</span></span>
<span class="line"><span>GET /_cat/indices?v&amp;h=health,status,index,docs.count</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2. 创建索引（生活笔记场景 + IK双分词）</span></span>
<span class="line"><span>PUT /life_note</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;mappings&quot;: {</span></span>
<span class="line"><span>    &quot;properties&quot;: {</span></span>
<span class="line"><span>      &quot;title&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;text&quot;,</span></span>
<span class="line"><span>        &quot;analyzer&quot;: &quot;ik_max_word&quot;,</span></span>
<span class="line"><span>        &quot;search_analyzer&quot;: &quot;ik_smart&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;content&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;text&quot;,</span></span>
<span class="line"><span>        &quot;analyzer&quot;: &quot;ik_max_word&quot;,</span></span>
<span class="line"><span>        &quot;search_analyzer&quot;: &quot;ik_smart&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;type&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;keyword&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;author&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;keyword&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;record_time&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;date&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3. 查看索引结构</span></span>
<span class="line"><span>GET /life_note/_mapping</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 4. 查看索引配置</span></span>
<span class="line"><span>GET /life_note/_settings</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 5. 删除索引</span></span>
<span class="line"><span>DELETE /life_note</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ==========================</span></span>
<span class="line"><span># 文档 增删改查（生活日常案例）</span></span>
<span class="line"><span># ==========================</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 1. 新增文档（自动生成 ID）</span></span>
<span class="line"><span>POST /life_note/_doc</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;title&quot;: &quot;周末城市短途旅行攻略&quot;,</span></span>
<span class="line"><span>&quot;content&quot;: &quot;周末适合周边短途出行，打卡公园、小吃街，放松日常工作压力，出行尽量避开早晚高峰&quot;,</span></span>
<span class="line"><span>&quot;type&quot;: &quot;旅行生活&quot;,</span></span>
<span class="line"><span>&quot;author&quot;: &quot;日常记录&quot;,</span></span>
<span class="line"><span>&quot;record_time&quot;: &quot;2026-04-27&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2. 新增文档（指定自定义 ID）</span></span>
<span class="line"><span>PUT /life_note/_doc/3001</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;title&quot;: &quot;健康饮食与居家养生&quot;,</span></span>
<span class="line"><span>&quot;content&quot;: &quot;规律作息、清淡饮食，多吃蔬菜水果，减少熬夜，合理运动才能保持身体健康&quot;,</span></span>
<span class="line"><span>&quot;type&quot;: &quot;健康生活&quot;,</span></span>
<span class="line"><span>&quot;author&quot;: &quot;生活达人&quot;,</span></span>
<span class="line"><span>&quot;record_time&quot;: &quot;2026-04-27&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3. 根据 ID 查询单条</span></span>
<span class="line"><span>GET /life_note/_doc/3001</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 4. 查询全部文档</span></span>
<span class="line"><span>GET /life_note/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 5. 全文分词检索（IK中文分词，搜：健康 作息 旅行）</span></span>
<span class="line"><span>GET /life_note/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match&quot;: {</span></span>
<span class="line"><span>      &quot;content&quot;: &quot;健康 作息 旅行&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 6. 精确匹配查询（keyword 分类字段）</span></span>
<span class="line"><span>GET /life_note/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;term&quot;: {</span></span>
<span class="line"><span>      &quot;type&quot;: &quot;健康生活&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 7. 只返回指定字段</span></span>
<span class="line"><span>GET /life_note/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;_source&quot;: [&quot;title&quot;, &quot;type&quot;, &quot;author&quot;],</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 8. 分页 + 时间排序</span></span>
<span class="line"><span>GET /life_note/_search</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;from&quot;: 0,</span></span>
<span class="line"><span>&quot;size&quot;: 10,</span></span>
<span class="line"><span>&quot;sort&quot;: [</span></span>
<span class="line"><span>    {&quot;record_time&quot;: &quot;desc&quot;}</span></span>
<span class="line"><span>  ],</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 9. 局部更新文档（推荐）</span></span>
<span class="line"><span>POST /life_note/_update/3001</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;doc&quot;: {</span></span>
<span class="line"><span>    &quot;title&quot;: &quot;健康饮食与居家养生小技巧&quot;,</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;居家生活&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 10. 全量覆盖更新</span></span>
<span class="line"><span>PUT /life_note/_doc/3001</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;title&quot;: &quot;日常养生好习惯总结&quot;,</span></span>
<span class="line"><span>&quot;content&quot;: &quot;早睡早起合理运动，少吃油腻辛辣食物，保持良好心态，提升生活幸福感&quot;,</span></span>
<span class="line"><span>&quot;type&quot;: &quot;居家生活&quot;,</span></span>
<span class="line"><span>&quot;author&quot;: &quot;生活达人&quot;,</span></span>
<span class="line"><span>&quot;record_time&quot;: &quot;2026-04-27&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 11. 根据 ID 删除文档</span></span>
<span class="line"><span>DELETE /life_note/_doc/3001</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 12. 条件批量删除</span></span>
<span class="line"><span>POST /life_note/_delete_by_query</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match&quot;: {</span></span>
<span class="line"><span>      &quot;author&quot;: &quot;日常记录&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 13. 统计文档总数</span></span>
<span class="line"><span>GET /life_note/_count</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 14. 清空索引数据（保留表结构）</span></span>
<span class="line"><span>POST /life_note/_delete_by_query</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;query&quot;: {</span></span>
<span class="line"><span>    &quot;match_all&quot;: {}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ==========================</span></span>
<span class="line"><span># IK 分词测试（生活文案）</span></span>
<span class="line"><span># ==========================</span></span>
<span class="line"><span></span></span>
<span class="line"><span># IK 细粒度分词（入库存储使用）</span></span>
<span class="line"><span>POST /_analyze</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;analyzer&quot;: &quot;ik_max_word&quot;,</span></span>
<span class="line"><span>&quot;text&quot;: &quot;周末短途旅行 居家健康养生 日常美好生活记录&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># IK 智能分词（搜索查询使用）</span></span>
<span class="line"><span>POST /_analyze</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>&quot;analyzer&quot;: &quot;ik_smart&quot;,</span></span>
<span class="line"><span>&quot;text&quot;: &quot;周末短途旅行 居家健康养生 日常美好生活记录&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这样，我们基于 ik 分词器实现了中文的关键词检索。</p><p>学习 ElasticSearch 还要知道一个 bm25 的算法。</p><p>虽然用 ik 分词器分词后，建立倒排索引表，然后就可以检索了。</p><p>但是检索到的文档相关性怎么样，如何排序？</p><p>这就是 bm25 算法做的。</p><p>BM25（Best Matching 25）是全文检索的相关性打分算法</p><p>它有一些策略，比如：</p><ul><li>词频饱和：词出现次数到一定程度，分数不再涨（防堆砌）。</li><li>文档长度归一化：越长的文档，越 “扣分”（公平对比长短文）。</li><li>稀有词权重高：少见词（如 “IK 分词”）比常用词（如 “的”）更重要。</li></ul><p>总之，BM25 算法是公平、高效、稳定的关键词排序算法，ES 默认用它，后面 RAG 做关键词检索也是依赖这个。</p><p>理解了 ik 分词器 + 倒排索引 + BM25 算法，就理解了 ElasticSearch 了。</p><h2 id="总结" tabindex="-1"><strong>总结</strong> <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**&quot;">​</a></h2><p>这节我们学了 ElasticSearch 做全文检索。</p><p>用 docker compose 安装了 es 和它的可视化控制台 kibana</p><p>es 里只有索引、文档这两层。</p><p>我们通过 http 的接口创建了索引、文档，做了文档的增删改查。</p><p>es 的检索原理就是倒排索引，也就是关键词 -&gt; 文档的索引表，这是它能实现海量文档毫秒级检索的核心。</p><p>入库的时候会对类型为 text 的字段分词，放到倒排索引表（类型为 keyword 的字段不会）。</p><p>检索的时候会把 query 也分词，分别检索倒排索引表，把查到的文档合并返回。</p><p>结果还会用 BM25 算法来排序。</p><p>中文分词我们安装了 IK 分词器，入库用 ik_max_word 细粒度分词，检索用 ik_samrt 高效分词。</p><p>理解了倒排索引表 + BM25 算法 + IK 分词器，串起来就理解了 ElasticSearch 的核心了</p>`,90)])])}const d=n(e,[["render",t]]);export{m as __pageData,d as default};
